// Factorial: n! = n × (n-1)!  y  0! = 1
function factorial(n, nivel = 0) {
  const sangria = "  ".repeat(nivel);
  console.log(sangria + "factorial(" + n + ") empieza");
  if (n === 0) {                                   // CASO BASE: se responde sin preguntar de nuevo
    console.log(sangria + "factorial(0) devuelve 1");
    return 1;
  }
  const chico = factorial(n - 1, nivel + 1);       // PASO RECURSIVO: confiamos en que esto ya funciona
  const resultado = n * chico;
  console.log(sangria + "factorial(" + n + ") devuelve " + n + " × " + chico + " = " + resultado);
  return resultado;
}
console.log("resultado final:", factorial(4));

// Sumar una lista: suma([]) = 0  y  suma([x, ...resto]) = x + suma(resto)
function suma(lista, desde = 0) {
  if (desde === lista.length) return 0;            // caso base: no queda nada por sumar
  return lista[desde] + suma(lista, desde + 1);    // paso recursivo: el primero + la suma de todo lo demás
}
console.log(suma([3, 1, 4, 1, 5]));                // 14
console.log(suma([]));                              // 0

// Contar las cajas de un pallet: una caja puede traer unidades sueltas o más cajas adentro
const pallet = { cajas: [ { unidades: 12 }, { cajas: [ { unidades: 6 }, { cajas: [ { unidades: 2 } ] } ] }, { unidades: 24 } ] };
function totalUnidades(caja) {
  if (caja.unidades !== undefined) return caja.unidades;      // caso base: una caja con unidades sueltas
  let total = 0;
  for (const interior of caja.cajas) total += totalUnidades(interior);   // paso recursivo: cada caja de adentro
  return total;
}
console.log(totalUnidades(pallet));                // 12 + 6 + 2 + 24 = 44

// Potencia: x elevado a n, de dos maneras. Contamos las llamadas.
let llamadas = 0;
function lenta(x, n) {                              // x^n = x · x^(n-1)
  llamadas++;
  if (n === 0) return 1n;
  return x * lenta(x, n - 1);
}
function rapida(x, n) {                             // x^n = (x^(n/2))² si n es par; x · x^(n-1) si es impar
  llamadas++;
  if (n === 0) return 1n;
  if (n % 2 === 0) { const mitad = rapida(x, n / 2); return mitad * mitad; }
  return x * rapida(x, n - 1);
}
for (const n of [10, 100, 1000]) {
  llamadas = 0; const a = lenta(3n, n); const llamadasLenta = llamadas;
  llamadas = 0; const b = rapida(3n, n); const llamadasRapida = llamadas;
  console.log("3^" + n, "| mismo resultado:", a === b, "| llamadas lenta:", llamadasLenta, "| rápida:", llamadasRapida);
}

// Fibonacci ingenuo: fib(n) = fib(n-1) + fib(n-2), con fib(0) = 0 y fib(1) = 1
let llamadas = 0;
function fib(n) {
  llamadas++;
  if (n < 2) return n;                              // casos base: hay DOS
  return fib(n - 1) + fib(n - 2);                   // paso recursivo: dos llamadas por cada una
}
function fibConBucle(n) {                           // la misma sucesión sin recursión: n pasos
  let a = 0, b = 1;
  for (let i = 0; i < n; i++) [a, b] = [b, a + b];
  return a;
}
for (const n of [5, 10, 15, 20, 25, 27]) {
  llamadas = 0;
  const t = performance.now();
  const r = fib(n);
  const ms = performance.now() - t;
  console.log("fib(" + n + ") =", r, "| llamadas:", llamadas, "| tiempo:", ms.toFixed(1), "ms | con bucle:", fibConBucle(n));
}

// Torres de Hanoi: mover n discos de «origen» a «destino» usando «auxiliar»
// Regla: de a un disco por vez, y nunca uno grande sobre uno chico.
const movimientos = [];
function hanoi(n, origen, destino, auxiliar) {
  if (n === 0) return;                                    // caso base: sin discos no hay nada que mover
  hanoi(n - 1, origen, auxiliar, destino);                // 1) los n-1 de arriba, a un costado
  movimientos.push("disco " + n + ": " + origen + " -> " + destino);   // 2) el más grande, directo
  hanoi(n - 1, auxiliar, destino, origen);                // 3) los n-1 encima del grande
}
hanoi(3, "A", "C", "B");
console.log(movimientos.length + " movimientos");
movimientos.forEach((m, i) => console.log((i + 1) + ". " + m));

// ¿Cuántos movimientos hacen falta? Probemos con más discos
for (const n of [1, 2, 3, 4, 5, 10, 20]) {
  movimientos.length = 0;
  hanoi(n, "A", "C", "B");
  console.log(n + " discos:", movimientos.length, "movimientos | 2^n - 1 =", 2 ** n - 1);
}

// Dos formas de recorrer una cadena MUY profunda: cada nodo apunta a un solo hijo (como una lista enlazada)
function cadena(profundidad) {
  let raiz = { valor: 1, hijo: null };
  let actual = raiz;
  for (let i = 1; i < profundidad; i++) { actual.hijo = { valor: 1, hijo: null }; actual = actual.hijo; }
  return raiz;
}
function contarRecursivo(nodo) {                          // la pila de llamadas lleva la cuenta
  if (nodo === null) return 0;
  return 1 + contarRecursivo(nodo.hijo);
}
function contarConPilaPropia(raiz) {                      // la misma idea con una pila que manejás vos
  const porVisitar = [raiz];
  let total = 0;
  while (porVisitar.length > 0) {
    const nodo = porVisitar.pop();
    if (nodo === null) continue;
    total++;
    porVisitar.push(nodo.hijo);
  }
  return total;
}
for (const n of [1000, 5000, 50000, 1000000]) {
  const c = cadena(n);
  let r1;
  try { r1 = contarRecursivo(c); } catch (e) { r1 = e.name; }
  console.log(String(n).padStart(8), "| recursiva:", r1, "| con pila propia:", contarConPilaPropia(c));
}

'use strict';
function sumaCola(n, acc) { return n === 0 ? acc : sumaCola(n - 1, acc + n); }   // la llamada es lo último que se hace
function sumaNormal(n) { return n === 0 ? 0 : n + sumaNormal(n - 1); }            // después de volver todavía falta sumar n
for (const n of [1000, 100000, 10000000]) {
  for (const [nombre, f] of [["de cola", (k) => sumaCola(k, 0)], ["normal ", sumaNormal]]) {
    try { console.log(nombre, n, f(n)); } catch (e) { console.log(nombre, n, e.name); }
  }
}

// Un árbol de categorías de un depósito: cada nodo tiene su stock propio y una lista de subcategorías
const deposito = {
  nombre: "Depósito", stock: 10, hijos: [
    { nombre: "Bebidas", stock: 0, hijos: [
      { nombre: "Gaseosas", stock: 120, hijos: [] },
      { nombre: "Aguas", stock: 20, hijos: [
        { nombre: "Con gas", stock: 30, hijos: [] },
        { nombre: "Sin gas", stock: 50, hijos: [] },
      ] },
    ] },
    { nombre: "Limpieza", stock: 45, hijos: [] },
  ],
};

// La forma del código copia la forma del dato: un nodo = su propio valor + lo que valga cada hijo
function totalStock(nodo) {
  let total = nodo.stock;
  for (const hijo of nodo.hijos) total += totalStock(hijo);   // si no hay hijos, el for no hace nada: ese es el caso base
  return total;
}
function profundidad(nodo) {
  let masHondo = 0;
  for (const hijo of nodo.hijos) masHondo = Math.max(masHondo, profundidad(hijo));
  return 1 + masHondo;
}
function mostrar(nodo, nivel = 0) {
  console.log("  ".repeat(nivel) + nodo.nombre + " (" + totalStock(nodo) + ")");
  for (const hijo of nodo.hijos) mostrar(hijo, nivel + 1);
}
function rutaA(nodo, buscado) {                                // devuelve el camino hasta el nodo, o null si no está
  if (nodo.nombre === buscado) return [nodo.nombre];
  for (const hijo of nodo.hijos) {
    const ruta = rutaA(hijo, buscado);
    if (ruta !== null) return [nodo.nombre, ...ruta];
  }
  return null;
}
mostrar(deposito);
console.log("stock total:", totalStock(deposito), "| niveles:", profundidad(deposito));
console.log("ruta a «Sin gas»:", rutaA(deposito, "Sin gas").join(" > "));
console.log("ruta a «Lácteos»:", rutaA(deposito, "Lácteos"));

// Una versión simplificada (mía) de lo que hace «fusionar» en Senda: lo traducido va encima del original
function fusionar(base, trad) {
  if (trad === undefined || trad === null) return base;                        // caso base: sin traducción, queda el original
  if (Array.isArray(trad)) return trad.map((x, i) => fusionar(base?.[i], x));   // una lista: elemento por elemento
  if (typeof trad === "object") {                                               // un objeto: clave por clave
    const salida = { ...base };
    for (const [clave, valor] of Object.entries(trad)) salida[clave] = fusionar(base?.[clave], valor);
    return salida;
  }
  return trad;                                                                  // caso base: un texto o un número reemplaza al original
}

